@notation({A} ~ " = " ~ {B})
relation SetEq(T: Any, A B: Set<T>): Prop {
    |- {
        Subset(A, B);
        Subset(B, A);
    }
}

@notation({A} ~ " = " ~ {B})
relation SetEq(T: Any, A B: Set<T>): Prop {
    |- {
        Subset(A, B);
        Subset(B, A);
    }
}

-- use it by name:
--   SetEq(A, B)
-- unfolds to the two Subset goals above

@notation({f} ~ " = " ~ {g})
relation FunctionEq(X Y: Set<Any>, f g: Function<X, Y>): Prop {
    forall x in X
    |- f(x) = g(x)
}

-- same idea as Lean funext:
-- agree on every input → treat as the same function
